/* selectMasterMdCtBuyerChargeEntryList */ SELECT A.SLG_ID, A.COM_CODE, B.COM_NAME_LOC AS COM_NAME, A.COL01_DATA AS USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.COL01_DATA AND STATUS <> 'D') AS USER_NAME, A.COL02_DATA AS MENU_ID, (SELECT NAME FROM KX_MENUINFO WHERE MENU_ID = A.COL02_DATA) AS MENU_NAME, A.COL03_DATA AS USER_ID_M, A.COL04_DATA, A.COL05_DATA, A.IMP_NOTE, A.COL06_DATA, A.COL07_DATA, A.COL08_DATA, A.COL09_DATA, A.COL10_DATA, A.OPEN_DATE, A.CLOSE_DATE, B.COM_TYPE FROM BNTSLGIMP A, ICOMCMPY B WHERE A.COM_CODE(+) = B.COM_CODE AND A.SLG_ID = 'P07-0000020' AND B.BUSINESS_COND = #{st_com_gubun}
AND A.COM_CODE = #{st_com_code}
AND B.USER_ID = #{st_user_id}

mapper.update:
 /*updateMasterMdAmUserFirstPage*/
	UPDATE BNTSLGIMP
	SET COL01_DATA=#{USER_ID},
	    COL02_DATA=#{MENU_ID},
	    COL04_DATA=#{COL04_DATA}
	WHERE SLG_ID = 'P07-0000020'
	AND COM_CODE = #{COM_CODE}

  /* deleteMasterMdAmUserFirstPage */
	 DELETE FROM  BNTSLGIMP
	 WHERE SLG_ID = 'P07-0000020'
	 AND COM_CODE = #{COM_CODE}
